/**
 * Single source of truth for the architecture/workflow diagrams (five workflows and the security path).
 *
 * The interactive page (React Flow) and the source-controlled Mermaid files in docs/architecture/
 * are both generated from this file, so they cannot drift apart. Every node says what it is in the
 * code base TODAY through `state`:
 *   implemented — runs in this app            partial  — exists but narrower than its name
 *   planned     — not built yet               optional — built but off until configured
 *   external    — a third-party system        candidate — an open-source component under evaluation
 * A node's live health comes from `probe` (see status.ts); nodes without code have no probe and are
 * shown as Disabled, never as healthy.
 */
export type NodeState = "implemented" | "partial" | "planned" | "optional" | "external" | "candidate";
export type NodeShape = "step" | "decision" | "store" | "terminal";
export type EdgeKind = "normal" | "failure" | "optional" | "loop";
export type ProbeKey =
  | "frontend" | "auth" | "api" | "db" | "queue" | "scheduler" | "ai" | "publishing" | "verification"
  | "inbox" | "webhooks" | "private_replies" | "ads" | "media" | "connections" | "meta_app" | "zernio"
  | "analytics" | "leads" | "automation_rules"
  | "sec_browser" | "sec_signin" | "sec_mfa" | "sec_session" | "sec_connections" | "sec_db" | "sec_env" | "sec_keys" | "sec_webhooks" | "sec_ads";

export interface L { en: string; it: string }
export interface ArchNode {
  id: string;
  label: L;
  col: number;
  row: number;
  shape: NodeShape;
  state: NodeState;
  /** Service / module that owns this step. */
  service: string;
  purpose: L;
  technology: string;
  /** Repository path or documentation URL. */
  link: string;
  probe?: ProbeKey;
  deps: string[];
  troubleshoot: L;
}
export interface ArchEdge { from: string; to: string; label?: L; kind?: EdgeKind }
export interface ArchDiagram { id: DiagramId; file: string; title: L; summary: L; nodes: ArchNode[]; edges: ArchEdge[] }
export type DiagramId = "system" | "account-connections" | "publishing-learning" | "advertising" | "messaging-leads" | "security";

const REPO = "https://github.com/codepheonix/spagnol/tree/main/";
const l = (en: string, it: string): L => ({ en, it });

interface NodeOpts { shape?: NodeShape; state?: NodeState; service: string; purpose: L; tech: string; link: string; probe?: ProbeKey; deps?: string[]; fix: L }
const n = (id: string, col: number, row: number, label: L, o: NodeOpts): ArchNode => ({ id, label, col, row, shape: o.shape ?? "step", state: o.state ?? "implemented", service: o.service, purpose: o.purpose, technology: o.tech, link: o.link.startsWith("http") ? o.link : REPO + o.link, probe: o.probe, deps: o.deps ?? [], troubleshoot: o.fix });
const e = (from: string, to: string, label?: L, kind?: EdgeKind): ArchEdge => ({ from, to, label, kind });

