export const DIAGRAMS: ArchDiagram[] = [system, accounts, publishing, advertising, messaging, security];
export const getDiagram = (id: string): ArchDiagram | undefined => DIAGRAMS.find((d) => d.id === id);

// ---------------------------------------------------------------------------------------------
// Mermaid export (docs/architecture/*.mmd are generated from the definitions above)
// ---------------------------------------------------------------------------------------------
const esc = (s: string) => s.replace(/"/g, "'");
export function toMermaid(d: ArchDiagram): string {
  const lines: string[] = [`%% GENERATED from packages/core/src/architecture/diagrams.ts — run \`pnpm diagrams\`; do not edit by hand.`, `%% ${d.title.en}: ${d.summary.en}`, "flowchart TD"];
  for (const node of d.nodes) {
    const text = `"${esc(node.label.en)}${node.state === "implemented" || node.state === "external" ? "" : `<br/><i>${node.state}</i>`}"`;
    const shape = node.shape === "decision" ? `{${text}}` : node.shape === "store" ? `[(${text})]` : node.shape === "terminal" ? `([${text}])` : `[${text}]`;
    lines.push(`  ${node.id}${shape}:::${node.state}`);
  }
  for (const edge of d.edges) {
    const arrow = edge.kind === "failure" ? "-.->" : edge.kind === "optional" ? "-.->" : edge.kind === "loop" ? "==>" : "-->";
    lines.push(`  ${edge.from} ${arrow}${edge.label ? `|"${esc(edge.label.en)}"|` : ""} ${edge.to}`);
  }
  lines.push("  classDef implemented fill:#12352b,stroke:#6fb89b,color:#ede8e2", "  classDef partial fill:#3a3115,stroke:#d9a441,color:#ede8e2", "  classDef planned fill:#272422,stroke:#918982,color:#b8b0a8,stroke-dasharray:5 4", "  classDef candidate fill:#272422,stroke:#8daad4,color:#b8b0a8,stroke-dasharray:5 4", "  classDef optional fill:#1f2a3a,stroke:#8daad4,color:#ede8e2,stroke-dasharray:2 3", "  classDef external fill:#1b1917,stroke:#4a4440,color:#ede8e2");
  return lines.join("\n") + "\n";
}
